3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Identifies the owners that make up a household — those sharing a last name and address,
15	 * compared case-insensitively with collapsed whitespace. Used both to guard against
16	 * accidental duplicates ({@link EnsureUniqueHousehold}) and to group knowing house-mates
17	 * under a shared, stable household id ({@link AssignHousehold}).
18	 */
19	final class Households {
20	
21	    private Households() {
22	    }
23	
24	    /** Existing owners whose last name and address match the given household. */
25	    static List<Owner> membersAt(OwnerRepository repository, String lastName, String address) {
26	        String key = key(lastName, address);
27	        List<Owner> members = new ArrayList<>();
28	        for (Owner owner : repository.findAll()) {
29	            if (key.equals(key(owner.getLastName(), owner.getAddress()))) {
30	                members.add(owner);
31	            }
32	        }
33	        return members;
34	    }
35	
36	    /**
37	     * A stable identifier for the household with the given last name and address. Derived
38	     * from the normalized key, so every member of the same household resolves to the same
39	     * value regardless of when they are created.
40	     */
41	    static String householdId(String lastName, String address) {
42	        return "HH-" + sha256Hex(key(lastName, address)).substring(0, 24).toUpperCase(Locale.ROOT);
43	    }
44	
45	    /** The normalized last name and address joined into a single household key. */
46	    private static String key(String lastName, String address) {
47	        return normalize(lastName) + '\n' + normalize(address);
48	    }
49	
50	    /** Case-fold and collapse whitespace so trivial spacing/casing differences still match. */
51	    private static String normalize(String value) {
52	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
53	    }
54	
55	    private static String sha256Hex(String value) {
56	        try {
57	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
58	            StringBuilder hex = new StringBuilder(digest.length * 2);
59	            for (byte b : digest) {
60	                hex.append(String.format("%02x", b));
61	            }
62	            return hex.toString();
63	        }
64	        catch (NoSuchAlgorithmException ex) {
65	            throw new IllegalStateException("SHA-256 not available", ex);
66	        }
67	    }
68	}
