1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * When a create request opts in with {@code sharesHousehold=true} and there are existing
12	 * owners at the same household (same last name and address, compared case-insensitively
13	 * with collapsed whitespace), assigns the built owner and those existing members the same
14	 * stable {@code householdId}. Runs after {@link BuildOwner} and before {@link SaveOwner}
15	 * so the id is stored and returned with the new owner; existing members without one are
16	 * back-filled so the whole household shares it. A request that does not opt in, or that
17	 * has no existing house-mates, leaves the owner's {@code householdId} unset.
18	 */
19	public class AssignHousehold {
20	
21	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
22	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        List<Owner> members = Households.membersAt(ownerRepository, owner.getLastName(), owner.getAddress());
26	        if (members.isEmpty()) {
27	            return;
28	        }
29	        String householdId = Households.householdId(owner.getLastName(), owner.getAddress());
30	        for (Owner member : members) {
31	            if (!householdId.equals(member.getHouseholdId())) {
32	                member.setHouseholdId(householdId);
33	                ownerRepository.save(member);
34	            }
35	        }
36	        owner.setHouseholdId(householdId);
37	    }
38	}
