8	/**
9	 * Rejects a create request whose last name and address already belong to an existing
10	 * owner, comparing both case-insensitively with collapsed whitespace. Runs before
11	 * {@link BuildOwner}, so a collision is a 409 via {@link DuplicateHouseholdException}
12	 * before any owner is built or saved. A request that opts in with
13	 * {@code sharesHousehold=true} is allowed through; {@link AssignHousehold} then groups it
14	 * with the existing owners under a shared household id.
15	 */
16	public class EnsureUniqueHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        if (!Households.membersAt(ownerRepository, request.getLastName(), request.getAddress()).isEmpty()) {
24	            throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
25	        }
26	    }
27	}
