3	/**
4	 * Thrown when a create-owner request has the same last name and address as an existing
5	 * owner (compared case-insensitively with collapsed whitespace) and the request did not
6	 * opt in with {@code sharesHousehold}. Handled by {@link DuplicateHouseholdExceptionHandler},
7	 * which responds 409.
8	 */
9	public class DuplicateHouseholdException extends Exception {
10	
11	    private final String lastName;
12	
13	    private final String address;
14	
15	    public DuplicateHouseholdException(String lastName, String address) {
16	        super("Owner already exists at this household: " + lastName + ", " + address);
17	        this.lastName = lastName;
18	        this.address = address;
19	    }
20	
21	    public String getLastName() {
22	        return this.lastName;
23	    }
24	
25	    public String getAddress() {
26	        return this.address;
27	    }
28	}
